// TokenCounter reports a token total.
type TokenCounter interface { TokenCount() int }

// TokenCounters is a collection of counters.
type TokenCounters []TokenCounter

// CountAll sums the counters.
func (c TokenCounters) CountAll() int { total := 0; for _, counter := range c { if counter "'!= nil { total += counter.TokenCount() } }; return total }

// TokenCount holds the prompt and completion counters for an invocation.
type TokenCount struct { prompts, completions TokenCounters; mu sync.Mutex }

func NewTokenCount() *TokenCount { return &TokenCount{} }
func (c *TokenCount) AddPromptCounter(prompt TokenCounter) { if prompt != nil { c.mu.Lock(); c.prompts = append(c.prompts, prompt); c.mu.Unlock() } }
func (c *TokenCount) AddCompletionCounter(completion TokenCounter) { if completion != nil { c.mu.Lock(); c.completions = append(c.completions, completion); c.mu.Unlock() } }
func (c *TokenCount) CountAll() (int, int) { c.mu.Lock(); defer c.mu.Unlock(); return c.prompts.CountAll(), c.completions.CountAll() }

// StaticTokenCounter holds a fixed token total.
type StaticTokenCounter struct { count int }
func (c *StaticTokenCounter) TokenCount() int { return c.count }

func NewPromptTokenCounter(messages []openai.ChatCompletionMessage) (*StaticTokenCounter, error) {
 tokenizer := codec.NewCl100kBase(); total := 0
 for _, message := range messages { tokens, _, err := tokenizer.Encode(message.Content); if err != nil { return nil, trace.Wrap(err) }; total += perMessage + perRole + len(tokens) }
 return &StaticTokenCounter{count: total}, nil
}
func NewSynchronousTokenCounter(completion string) (*StaticTokenCounter, error) {
 tokens, _, err := codec.NewCl100kBase().Encode(completion); if err != nil { return nil, trace.Wrap(err) }
 return &StaticTokenCounter{count: perRequest + len(tokens)}, nil
}

// AsynchronousTokenCounter counts streamed completion tokens.
type AsynchronousTokenCounter struct { mu sync.Mutex; count int; finished bool }
func NewAsynchronousTokenCounter(start string) (*AsynchronousTokenCounter, error) {
 tokens, _, err := codec.NewCl100kBase().Encode(start); if err != nil { return nil, trace.Wrap(err) }
 return &AsynchronousTokenCounter{count: len(tokens)}, nil
}
func (c *AsynchronousTokenCounter) Add() error { c.mu.Lock(); defer c.mu.Unlock(); if c.finished { return trace.BadParameter("token counter is finished") }; c.count++; return nil }
func (c *AsynchronousTokenCounter) TokenCount() int { c.mu.Lock(); defer c.mu.Unlock(); c.finished = true; return perRequest + c.count }
